def winners(a,b):
 return tuple(('**' if x>=max(a,b)-1e-12 else '')+f'{x:.6f}'+('**' if x>=max(a,b)-1e-12 else '') for x in [a,b])
def main():
 if (O/'report_completion.json').exists():raise ValueError('Preserve completed report; create a new version')
