 O.mkdir(exist_ok=True);F=O/'visual_figures';T=O/'visual_tables';F.mkdir(exist_ok=True);T.mkdir(exist_ok=True)
 aggregate=json.loads((A/'aggregate_performance.json').read_text());performance=json.loads((A/'performance.json').read_text());pairs=[];assetpairs=[]
